import org.jsoup.select.Elements;
import org.jsoup.select.Node;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Element_equals_TriageGen1Test {

    @Test
    public void testEquals_SameInstance_ReturnsTrue() {
        Element element = new Element(Tag.valueOf("a"), "");
        assertTrue(element.equals(element));
    }

    @Test
    public void testEquals_DifferentInstance_ReturnsFalse() {
        Element element1 = new Element(Tag.valueOf("a"), "");
        Element element2 = new Element(Tag.valueOf("b"), "");
        assertFalse(element1.equals(element2));
    }

    @Test
    public void testEquals_NullObject_ReturnsFalse() {
        Element element = new Element(Tag.valueOf("a"), "");
        assertFalse(element.equals(null));
    }

    @Test
    public void testEquals_DifferentClass_ReturnsFalse() {
        Element element = new Element(Tag.valueOf("a"), "");
        String string = "test";
        assertFalse(element.equals(string));
    }

    @Test
    public void testEquals_SuperclassEquals_ReturnsFalse() {
        Element element1 = new Element(Tag.valueOf("a"), "");
        Element element2 = new Element(Tag.valueOf("a"), "");
        assertFalse(element1.equals(element2));
    }

    @Test
    public void testEquals_SameElement_ReturnsTrue() {
        Element element1 = new Element(Tag.valueOf("a"), "");
        Element element2 = new Element(Tag.valueOf("a"), "");
        element1.setTag(Tag.valueOf("a"));
        element1.setBaseUri("");
        element1.setAttributes(Attributes.create());
        assertTrue(element1.equals(element2));
    }

    @Test
    public void testEquals_DifferentAttributes_ReturnsFalse() {
        Element element1 = new Element(Tag.valueOf("a"), "");
        Element element2 = new Element(Tag.valueOf("a"), "");
        element1.setAttributes(Attributes.create());
        element2.setAttributes(Attributes.create());
        element1.getAttributes().put("key", "value");
        assertFalse(element1.equals(element2));
    }
}
